window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-413a0750b1675869"]={"versions": [{"id": "FIG-413a0750b1675869", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm (Architekturspezifikation der AUTOSAR Adaptive Platform unter Nutzung des AUTOSAR-Metamodell-Stereotyps <code>«aapFunctionalCluster»</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Formale Spezifikation der Abhängigkeiten im Kapitel 5.1 (<em>Provided Interfaces</em>) der <code>AUTOSAR_AP_SWS_CommunicationManagement</code>.</li>\n<li>Dokumentiert den architektonischen Null-Befund: Das <em>Communication Management</em> (<code>ara::com</code>) stellt keine proprietären C++-Inter-Cluster-Schnittstellen (<em>Provided Interfaces</em>) für andere funktionale Cluster (wie <em>Execution Management</em>, <em>State Management</em> oder <em>IAM</em>) bereit (bestätigt durch Tabelle 5.1: <em>„No provided interfaces“</em>).</li>\n<li>Systemkontext: <code>ara::com</code> dient ausschließlich als Kommunikationsmiddleware für adaptive Applikationen sowie als Protokoll- und IPC-Endpunkt, nicht als funktionaler Dienstleister für Nachbar-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Entitäten:</strong></li>\n<li><strong>Komponente:</strong> <code>Communication Management</code> mit Stereotyp <code>«aapFunctionalCluster»</code>.</li>\n<li><strong>Eigenschaft / Deployment-Klassifikation:</strong> <code>daemon-based</code> – kennzeichnet die funktionale Implementierung als Hintergrund-Prozess/Dienst im POSIX-Betriebssystem (im Kontrast zu rein bibliotheksbasierten Clustern / <code>library-based</code>).</li>\n<li><strong>Schnittstellen & Beziehungen:</strong></li>\n<li><strong>Schnittstellen (Provided Interfaces):</strong> Keine (leere Menge). Es existieren weder UML-Lollipops noch Port-Definitionen.</li>\n<li><strong>Kardinalitäten / Assoziationen:</strong> Keine externen Abhängigkeiten oder Vererbungsbeziehungen dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Dynamik:</strong> Nicht zutreffend (statisches strukturelles Deklarationsdiagramm).</li>\n<li><strong>Architektonischer Kontrollfluss:</strong> Da keine direkten Inter-Cluster-APIs existieren, erfolgen weder synchrone Methodenaufrufe noch asynchrone Callbacks oder Notification-Pfade aus Nachbar-Clustern in das Management-Modul. Wenn andere funktionale Cluster netzwerkweit kommunizieren (z. B. <em>State Management</em> oder <em>UCM</em>), nutzen sie <code>ara::com</code> als reguläre Clients über generierte Service-Proxies/-Skeletons, nicht über interne Cluster-APIs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Plattform- & Stack-Entwickler:</strong></li>\n<li><strong>Prozessmodell:</strong> Die Einstufung <code>daemon-based</code> erfordert im Stack-Design die Bereitstellung mindestens eines separaten OS-Prozesses (z. B. SOME/IP-Daemon, IPC-Broker oder Service-Discovery-Daemon), der via <em>Execution Management</em> (<code>ara::exec</code>) per <em>Execution Manifest</em> konfiguriert und überwacht wird.</li>\n<li><strong>API-Vertrag:</strong> Es muss kein cluster-interner C++-Header-Export für fremde Plattform-Cluster gepflegt werden; die Implementierung kapselt alle Protokoll- und Routingmechanismen intern bzw. hinter der standardisierten <code>ara::com</code>-Applikationsschnittstelle.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Keine direkte Auswirkung auf die API-Nutzung von <code>ara::com</code> (Methoden, Events, Fields, Skeleton/Proxy-Generierung). Die Entkopplung garantiert, dass das Plattform-Subsystem keine versteckten Cluster-Kopplungen aufweist.</li>\n</ul>"}, {"id": "FIG-1e90f7277c644d74", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Komponentendiagramm (Architekturspezifikation der AUTOSAR Adaptive Platform unter Nutzung des AUTOSAR-Metamodell-Stereotyps <code>«aapFunctionalCluster»</code>).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong></li>\n<li>Formale Spezifikation der Abhängigkeiten im Kapitel 5.1 (<em>Provided Interfaces</em>) der <code>AUTOSAR_AP_SWS_CommunicationManagement</code>.</li>\n<li>Dokumentiert den architektonischen Null-Befund: Das <em>Communication Management</em> (<code>ara::com</code>) stellt keine proprietären C++-Inter-Cluster-Schnittstellen (<em>Provided Interfaces</em>) für andere funktionale Cluster (wie <em>Execution Management</em>, <em>State Management</em> oder <em>IAM</em>) bereit (bestätigt durch Tabelle 5.1: <em>„No provided interfaces“</em>).</li>\n<li>Systemkontext: <code>ara::com</code> dient ausschließlich als Kommunikationsmiddleware für adaptive Applikationen sowie als Protokoll- und IPC-Endpunkt, nicht als funktionaler Dienstleister für Nachbar-Cluster.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Dargestellte Entitäten:</strong></li>\n<li><strong>Komponente:</strong> <code>Communication Management</code> mit Stereotyp <code>«aapFunctionalCluster»</code>.</li>\n<li><strong>Eigenschaft / Deployment-Klassifikation:</strong> <code>daemon-based</code> – kennzeichnet die funktionale Implementierung als Hintergrund-Prozess/Dienst im POSIX-Betriebssystem (im Kontrast zu rein bibliotheksbasierten Clustern / <code>library-based</code>).</li>\n<li><strong>Schnittstellen & Beziehungen:</strong></li>\n<li><strong>Schnittstellen (Provided Interfaces):</strong> Keine (leere Menge). Es existieren weder UML-Lollipops noch Port-Definitionen.</li>\n<li><strong>Kardinalitäten / Assoziationen:</strong> Keine externen Abhängigkeiten oder Vererbungsbeziehungen dargestellt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Dynamik:</strong> Nicht zutreffend (statisches strukturelles Deklarationsdiagramm).</li>\n<li><strong>Architektonischer Kontrollfluss:</strong> Da keine direkten Inter-Cluster-APIs existieren, erfolgen weder synchrone Methodenaufrufe noch asynchrone Callbacks oder Notification-Pfade aus Nachbar-Clustern in das Management-Modul. Wenn andere funktionale Cluster netzwerkweit kommunizieren (z. B. <em>State Management</em> oder <em>UCM</em>), nutzen sie <code>ara::com</code> als reguläre Clients über generierte Service-Proxies/-Skeletons, nicht über interne Cluster-APIs.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Plattform- & Stack-Entwickler:</strong></li>\n<li><strong>Prozessmodell:</strong> Die Einstufung <code>daemon-based</code> erfordert im Stack-Design die Bereitstellung mindestens eines separaten OS-Prozesses (z. B. SOME/IP-Daemon, IPC-Broker oder Service-Discovery-Daemon), der via <em>Execution Management</em> (<code>ara::exec</code>) per <em>Execution Manifest</em> konfiguriert und überwacht wird.</li>\n<li><strong>API-Vertrag:</strong> Es muss kein cluster-interner C++-Header-Export für fremde Plattform-Cluster gepflegt werden; die Implementierung kapselt alle Protokoll- und Routingmechanismen intern bzw. hinter der standardisierten <code>ara::com</code>-Applikationsschnittstelle.</li>\n<li><strong>Applikations-Entwickler:</strong></li>\n<li>Keine direkte Auswirkung auf die API-Nutzung von <code>ara::com</code> (Methoden, Events, Fields, Skeleton/Proxy-Generierung). Die Entkopplung garantiert, dass das Plattform-Subsystem keine versteckten Cluster-Kopplungen aufweist.</li>\n</ul>"}], "trans": [{"from": "FIG-413a0750b1675869", "to": "FIG-1e90f7277c644d74", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
